import { buildSurahTextFiles, parseMetadata, parseQuranText } from './parse';

const pad = (n: number) => String(n).padStart(3, '0');

/** Every generated file, keyed by path relative to the package root. Deterministic. */
export function buildGeneratedFiles(quranText: string, metadataXml: string): Map<string, string> {
  const meta = parseMetadata(metadataXml);
  const texts = buildSurahTextFiles(parseQuranText(quranText), meta);
  const files = new Map<string, string>();

  files.set('generated/surahs.json', `${JSON.stringify(meta, null, 2)}\n`);
  for (const t of texts) files.set(`generated/text/${pad(t.surah)}.json`, `${JSON.stringify(t)}\n`);

  const loaders = texts
    .map(
      (t) =>
        `  ${t.surah}: () => import('./text/${pad(t.surah)}.json', { with: { type: 'json' } }),`,
    )
    .join('\n');
  files.set(
    'generated/loaders.ts',
    `// Generated by scripts/generate.ts. Do not edit.\nimport type { SurahTextFile } from '../src/parse';\n\nexport const loaders: Record<number, () => Promise<{ default: SurahTextFile }>> = {\n${loaders}\n};\n`,
  );
  return files;
}
